static void rejects(const std::function<void()>& f){bool failed=false;try{f();}catch(const std::exception&){failed=true;}assert(failed);}
static std::string var(uint64_t n){std::string s;do{uint8_t b=n&127;n>>=7;s+=char(b|(n?128:0));}while(n);return s;}
static std::string bytes(unsigned id,std::string_view x){return var((id<<3)|2)+var(x.size())+std::string(x);}
static std::string number(unsigned id,uint64_t n){return var(id<<3)+var(n);}
static std::string piece(std::string name,unsigned type=1){return bytes(1,name)+std::string("\x15\0\0\0\0",5)+number(3,type);}
static void synthetic(const char* destination=nullptr){
 const std::string tr=number(3,2)+number(4,32000)+number(35,1)+number(40,0)+number(41,1)+number(42,2)+number(43,UINT64_MAX),norm=bytes(1,"identity")+bytes(2,"")+number(3,1)+number(4,0);
 std::string body=bytes(1,piece("<unk>",2))+bytes(1,piece("<s>",3))+bytes(1,piece("</s>",3));for(unsigned i=0;i<256;++i){char name[10];std::snprintf(name,sizeof(name),"<0x%02X>",i);body+=bytes(1,piece(name,6));}for(unsigned i=259;i<32000;++i)body+=bytes(1,piece("word"+std::to_string(i)));
 const auto tail=bytes(2,tr)+bytes(3,norm),valid=body+tail;assert(sentencepiece(valid).pieces.size()==32000);if(destination){std::ofstream out(destination,std::ios::binary);out.write(valid.data(),std::streamsize(valid.size()));assert(out.good());return;}
 for(auto raw:std::vector<std::string>{"",valid.substr(0,valid.size()-1),std::string(1024*1024+1,'x'),std::string("\x0b"),std::string("\x08\x01"),std::string(11,char(0x80)),std::string("\x0a\xff\xff\xff\xff\x0f"),bytes(1,bytes(1,"x"))+tail,bytes(1,piece("x",5))+tail,body+tail+bytes(2,tr),body+bytes(2,"")+tail,body+bytes(2,tr)+bytes(3,bytes(1,"nfkc")),body+bytes(2,tr)+bytes(3,norm+number(7,1)),body+bytes(1,piece("extra"))+tail,bytes(1,piece(std::string("x\0y",3)))+tail,bytes(1,piece(std::string(1,char(0xff))))+tail})rejects([&]{sentencepiece(raw);});
 rejects([&]{sentencepiece(bytes(1,piece("x")+number(3,1))+tail);});
 auto nonfinite=piece("x");const auto pos=nonfinite.find(char(0x15));nonfinite[pos+3]=char(0x80);nonfinite[pos+4]=char(0x7f);rejects([&]{sentencepiece(bytes(1,nonfinite)+tail);});
 auto wrong_bos=tr;const auto bos=number(41,1);wrong_bos.replace(wrong_bos.find(bos),bos.size(),number(41,32000));rejects([&]{sentencepiece(body+bytes(2,wrong_bos)+bytes(3,norm));});
 rejects([&]{json(std::string(40,'[')+"0"+std::string(40,']'));});
 rejects([&]{json("{\"a\":1,\"a\":2}");});rejects([&]{json("{\"a\":{\"b\":1,\"b\":2}}");});std::puts("PASS synthetic malformed/range/wire/duplicates/nonfinite/UTF8");
}
static std::vector<int> tokens(const llama_vocab* v,const std::string& text,bool a,bool s){std::vector<int> out(512);int n=llama_tokenize(v,text.data(),int(text.size()),out.data(),int(out.size()),a,s);assert(n>=0);out.resize(n);return out;}
int main(int argc,char** argv){if(argc==3&&std::string(argv[1])=="--write-synthetic"){synthetic(argv[2]);return 0;}if(argc==3&&std::string(argv[1])=="--vocab-only"){auto meta=construct(argv[2]);llama_backend_init();auto params=llama_model_default_params();params.vocab_only=true;params.n_gpu_layers=0;auto* model=llama_model_init_from_user(meta.get(),nullptr,nullptr,params);assert(model&&llama_vocab_n_tokens(llama_model_get_vocab(model))==32000);llama_model_free(model);llama_backend_free();std::puts("VOCAB_ONLY_PASS");return 0;}if(argc==3&&std::string(argv[1])=="--construct"){try{auto meta=construct(argv[2]);std::puts("CONSTRUCTOR_PASS");return 0;}catch(const std::exception& e){std::fprintf(stderr,"REJECT %s\n",e.what());return 1;}}synthetic();if(argc==1)return 0;assert(argc==3);auto meta=construct(argv[1]);gguf_init_params gp{true,nullptr};Metadata ref(gguf_init_from_file(argv[2],gp),gguf_free);assert(ref&&gguf_get_n_tensors(ref.get())==0);unsigned compared=0;
 for(int64_t i=0;i<gguf_get_n_kv(meta.get());++i){const char* key=gguf_get_key(meta.get(),i);const auto j=gguf_find_key(ref.get(),key);if(j<0){assert(std::string(key)=="tokenizer.ggml.add_space_prefix"||std::string(key)=="tokenizer.ggml.add_eos_token"||std::string(key)=="tokenizer.ggml.remove_extra_whitespaces");continue;}const auto t=gguf_get_kv_type(meta.get(),i);assert(t==gguf_get_kv_type(ref.get(),j));if(t==GGUF_TYPE_STRING)assert(!std::strcmp(gguf_get_val_str(meta.get(),i),gguf_get_val_str(ref.get(),j)));else if(t==GGUF_TYPE_UINT32)assert(gguf_get_val_u32(meta.get(),i)==gguf_get_val_u32(ref.get(),j));else if(t==GGUF_TYPE_FLOAT32)assert(gguf_get_val_f32(meta.get(),i)==gguf_get_val_f32(ref.get(),j));else if(t==GGUF_TYPE_BOOL)assert(gguf_get_val_bool(meta.get(),i)==gguf_get_val_bool(ref.get(),j));else if(t==GGUF_TYPE_ARRAY){const auto n=gguf_get_arr_n(meta.get(),i);const auto at=gguf_get_arr_type(meta.get(),i);assert(n==gguf_get_arr_n(ref.get(),j)&&at==gguf_get_arr_type(ref.get(),j));if(at==GGUF_TYPE_STRING)for(size_t k=0;k<n;++k)assert(!std::strcmp(gguf_get_arr_str(meta.get(),i,k),gguf_get_arr_str(ref.get(),j,k)));else{assert(at==GGUF_TYPE_INT32||at==GGUF_TYPE_FLOAT32);assert(!std::memcmp(gguf_get_arr_data(meta.get(),i),gguf_get_arr_data(ref.get(),j),n*4));}}else assert(false);++compared;}
 llama_backend_init();auto params=llama_model_default_params();params.vocab_only=true;params.n_gpu_layers=0;auto* m=llama_model_init_from_user(meta.get(),nullptr,nullptr,params);auto* other=llama_model_load_from_file(argv[2],params);assert(m&&other);auto* a=llama_model_get_vocab(m);auto* b=llama_model_get_vocab(other);unsigned cases=0;
 for(const std::string& text:std::vector<std::string>{""," ","  a", "a  b\n\t", "\r\n",u8"café",u8"e\u0301",u8"日本語 😀",u8"\u00a0x\u2003", "<s>x</s>","<unk>","<0xFF>",std::string("a\0b",3)})for(bool add:{false,true})for(bool special:{false,true}){assert(tokens(a,text,add,special)==tokens(b,text,add,special));++cases;}
 llama_model_free(other);llama_model_free(m);llama_backend_free();std::printf("PASS metadata keys=%u arrays=32000x3 extra_tokenization_cases=%u\n",compared,cases);
}
